import{_ as t,o,c as a,a2 as l}from"./chunks/framework.Crpw6aS5.js";const h=JSON.parse('{"title":"1982年 · 会计假象与投资原则","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1982年.md","filePath":"05_quotes/by-year/1982年.md"}'),r={name:"05_quotes/by-year/1982年.md"};function c(u,e,p,s,q,b){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_1982年-·-会计假象与投资原则" tabindex="-1">1982年 · 会计假象与投资原则 <a class="header-anchor" href="#_1982年-·-会计假象与投资原则" aria-label="Permalink to &quot;1982年 · 会计假象与投资原则&quot;">​</a></h1><blockquote><p>会计数字是企业估值的起点，不是终点。我们相信，随着时间推移，未报告的盈利会通过资本增值，完全反映在我们的内在商业价值里。——巴菲特（52岁）</p></blockquote><p>本页收录1982年致股东信中的经典语录。这一年巴菲特讲透了会计收益与经济收益的区别，重申绝不发股稀释老股东价值的立场，对保险行业长期格局做出判断。ROE仅9.8%。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>会计数字是企业估值的起点，不是终点。</p></blockquote><blockquote><p>会计数字反映的&quot;会计&quot;收益，通常包含我们持股20%以上企业按比例分成的盈利。但持股低于20%，会计数字只包含我们从被投资单位分到的股息，这些持股低于20%的企业未分配盈利完全忽略不计。</p></blockquote><blockquote><p>我们更喜欢&quot;经济&quot;盈利概念，包含所有未分配盈利，不管持股比例多少。我们认为，留存盈利对所有所有者的价值，取决于这些盈利使用的效率，不取决于持股比例大小。</p></blockquote><blockquote><p>投资者永远可以按蟾蜍市价买蟾蜍。如果投资者出钱给公主，让公主付两倍价格获得亲吻蟾蜍的权利，那这些亲吻最好真能炸出点东西。</p></blockquote><blockquote><p>保险行业承保产能过剩，产品相对无差异，只有成本领先才能赚钱。未来要改善，必须供给收缩，而且是心理上的收缩。</p></blockquote><blockquote><p>GEICO就是我们讨论的，在商品产能过剩行业里高盈利的例外——公司拥有广泛可持续的成本优势。</p></blockquote><blockquote><p>我们有两个明星，米尔特·桑顿和弗洛伊德·泰勒，从加入我们以来每年都保持承保盈利。他们对自己运营保持 passion，所有者般的心态。</p></blockquote><blockquote><p>我们发股稀释内在价值，对收购方所有者会造成双重打击：首先，因为收购本身就亏了，给出去的价值比拿到的多；其次，市场对这种不关心所有者利益的管理层会给更低估值。</p></blockquote><blockquote><p>我们发行股份遵守一个简单基本原则：我们不会发行股份，除非我们收到的内在 business 价值和我们给出的一样多。</p></blockquote><blockquote><p>我们非常确定，未来每股增长率会下降——资本基数大幅扩大，自然如此。但如果增长率不能超过美国大型企业平均水平，我们会失望。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1982年ROE仅9.8%，是近年最低。主要受保险承保大幅恶化影响（综合成本率109.5%）。巴菲特在信中阐明了会计收益与经济收益的区别：大量未分配利润没体现在报表上，但它们真实存在，最终会反映在市值上。重申了不发股稀释股东价值的立场。预言保险行业供给过剩，竞争激烈，未来很难改善。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/1982年/翻译.html">01_letters/1982年/翻译</a> · <a href="/01_letters/1982年/核心总结.html">01_letters/1982年/核心总结</a> · <a href="/01_letters/1982年/思维导图.html">01_letters/1982年/思维导图</a></p>',21)])])}const n=t(r,[["render",c]]);export{h as __pageData,n as default};
